{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.chart1_myntra AS WITH m_latest_ts AS ( SELECT MARKETPLACE_MAPPED AS channel, MP_PO_NUMBER, MIN(ORDER_DATE) AS first_order_date, MAX(ORDER_DATE) AS last_order_date, MAX(SHIPPING_LAST_UPDATE_TIMESTAMP) AS max_ts FROM snitch_db.maplemonk.warehouse_mp_performance WHERE MP_PO_NUMBER IS NOT NULL AND MARKETPLACE_MAPPED IN (\'M-NOW\', \'M_NOW_WESTBENGAL\') GROUP BY MARKETPLACE_MAPPED, MP_PO_NUMBER HAVING MIN(ORDER_DATE) >= TO_DATE(\'2026-04-01\') ), m_latest_qty_candidates AS ( SELECT w.MARKETPLACE_MAPPED AS channel, w.MP_PO_NUMBER, w.MP_QTY FROM snitch_db.maplemonk.warehouse_mp_performance w JOIN m_latest_ts t ON t.channel = w.MARKETPLACE_MAPPED AND t.MP_PO_NUMBER = w.MP_PO_NUMBER AND t.max_ts = w.SHIPPING_LAST_UPDATE_TIMESTAMP ), m_po_latest_qty AS ( SELECT channel, MP_PO_NUMBER, COUNT(DISTINCT MP_QTY) AS distinct_qty_at_latest_ts, MAX(MP_QTY) AS resolved_mp_qty FROM m_latest_qty_candidates GROUP BY channel, MP_PO_NUMBER ), m_invoice_base AS ( SELECT w.MARKETPLACE_MAPPED AS channel, w.MP_PO_NUMBER, COUNT(DISTINCT w.SALEORDERITEMCODE) AS distinct_line_items, COUNT(*) AS total_line_item_rows, SUM( CASE WHEN w.SALE_ORDER_ITEM_STATUS <> \'CANCELLED\' THEN w.SUBORDER_QUANTITY ELSE 0 END ) AS invoiced_units FROM snitch_db.maplemonk.warehouse_mp_performance w JOIN m_latest_ts t ON t.channel = w.MARKETPLACE_MAPPED AND t.MP_PO_NUMBER = w.MP_PO_NUMBER GROUP BY w.MARKETPLACE_MAPPED, w.MP_PO_NUMBER ), m_po_base AS ( SELECT t.channel, t.MP_PO_NUMBER, DATE_TRUNC(\'MONTH\', t.first_order_date) AS order_month, q.resolved_mp_qty, i.invoiced_units, CASE WHEN q.distinct_qty_at_latest_ts > 1 THEN FALSE WHEN DATEDIFF(day, t.first_order_date, t.last_order_date) > 31 THEN FALSE WHEN i.distinct_line_items <> i.total_line_item_rows THEN FALSE WHEN i.invoiced_units > q.resolved_mp_qty * 1.05 THEN FALSE ELSE TRUE END AS po_data_trustworthy FROM m_latest_ts t JOIN m_po_latest_qty q ON q.channel = t.channel AND q.MP_PO_NUMBER = t.MP_PO_NUMBER LEFT JOIN m_invoice_base i ON i.channel = t.channel AND i.MP_PO_NUMBER = t.MP_PO_NUMBER ), m_grn_latest_ts AS ( SELECT MARKETPLACE_MAPPED AS channel, GRN_PO_BARCODE AS mp_po_number, GRN_LOT_BARCODE, MAX(COALESCE(GRN_RECEIVED_ON, SHIPPING_LAST_UPDATE_TIMESTAMP)) AS max_grn_ts FROM snitch_db.maplemonk.warehouse_mp_performance WHERE GRN_PO_BARCODE IS NOT NULL AND MARKETPLACE_MAPPED IN (\'M-NOW\', \'M_NOW_WESTBENGAL\') GROUP BY MARKETPLACE_MAPPED, GRN_PO_BARCODE, GRN_LOT_BARCODE ), m_grn_qty_candidates AS ( SELECT w.MARKETPLACE_MAPPED AS channel, w.GRN_PO_BARCODE AS mp_po_number, w.GRN_LOT_BARCODE, w.GRN_QUANTITY FROM snitch_db.maplemonk.warehouse_mp_performance w JOIN m_grn_latest_ts t ON t.channel = w.MARKETPLACE_MAPPED AND t.mp_po_number = w.GRN_PO_BARCODE AND t.GRN_LOT_BARCODE = w.GRN_LOT_BARCODE AND t.max_grn_ts = COALESCE(w.GRN_RECEIVED_ON, w.SHIPPING_LAST_UPDATE_TIMESTAMP) ), m_grn_by_lot AS ( SELECT channel, mp_po_number, GRN_LOT_BARCODE, MAX(GRN_QUANTITY) AS lot_grn_qty FROM m_grn_qty_candidates GROUP BY channel, mp_po_number, GRN_LOT_BARCODE ), m_grn_by_po AS ( SELECT channel, mp_po_number, SUM(lot_grn_qty) AS grn_units FROM m_grn_by_lot GROUP BY channel, mp_po_number ) SELECT p.order_month AS month, \'MYNTRA\' AS channel, COUNT(DISTINCT CASE WHEN p.po_data_trustworthy THEN p.MP_PO_NUMBER END) AS po_count, SUM(CASE WHEN p.po_data_trustworthy THEN p.resolved_mp_qty ELSE 0 END) AS po_raised, SUM(CASE WHEN p.po_data_trustworthy THEN p.invoiced_units ELSE 0 END) AS po_fulfilled, CASE WHEN MAX(CASE WHEN g.grn_units IS NOT NULL THEN 1 ELSE 0 END) = 1 THEN SUM(CASE WHEN p.po_data_trustworthy THEN COALESCE(g.grn_units, 0) ELSE 0 END) ELSE NULL END AS po_grned, CASE WHEN SUM(CASE WHEN p.po_data_trustworthy THEN p.resolved_mp_qty ELSE 0 END) > 0 THEN ROUND(SUM(CASE WHEN p.po_data_trustworthy THEN p.invoiced_units ELSE 0 END) / NULLIF(SUM(CASE WHEN p.po_data_trustworthy THEN p.resolved_mp_qty ELSE 0 END), 0) * 100, 2) ELSE NULL END AS fulfilled_pct, CASE WHEN MAX(CASE WHEN g.grn_units IS NOT NULL THEN 1 ELSE 0 END) = 1 AND SUM(CASE WHEN p.po_data_trustworthy THEN p.invoiced_units ELSE 0 END) > 0 THEN ROUND(SUM(CASE WHEN p.po_data_trustworthy THEN COALESCE(g.grn_units, 0) ELSE 0 END) / NULLIF(SUM(CASE WHEN p.po_data_trustworthy THEN p.invoiced_units ELSE 0 END), 0) * 100, 2) ELSE NULL END AS grned_pct, COUNT(DISTINCT CASE WHEN NOT p.po_data_trustworthy THEN p.MP_PO_NUMBER END) AS po_count_excluded FROM m_po_base p LEFT JOIN m_grn_by_po g ON g.channel = p.channel AND g.mp_po_number = p.MP_PO_NUMBER GROUP BY p.order_month ORDER BY month DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            